/*
 * Viscraft recipe: author a DIFFERENT product out of the reusable `glass-product` Look.
 *
 *   viscraft author create.mjs <new-project-directory> [--options <options.json>]
 *
 * The executable mechanics (loading, hashing, copying, licence carriage, Project
 * writing) belong to the Runtime. This file is the editable
 * creative declaration: the re-authored case proportions, the amber light-guide
 * palette, the two staged beats, Project ids and audio bed.
 *
 * The reusable module (`glass-product.mjs`) and its pinned `three@0.186.1`
 * closure are declared by the glass-product study's `three-files.mjs`: the
 * closure is resolved from the running Runtime (or an explicitly supplied donor
 * directory via `options.three`) and every digest is verified before writing.
 * The study's own scene (`glass-study.mjs` + `glass-study-scene.html`) and the
 * module's template scene page are local reads declared here. The Project
 * carries the Runtime's verbatim THIRD_PARTY_NOTICES.md. Hashes and revisions
 * are filled by the Runtime from the copied bytes.
 *
 * The study authors three real changes over the byte-identical module:
 * re-proportioned case geometry, a re-coloured light-guide material, and one
 * camera/lighting beat (the module's tight single-bud `explode` camera, held
 * with the product whole and lit by an exposure ramp). It authors TWO `browser`
 * picture Sources over that one entry — a close detail shot and a hero — so a
 * one-parameter edit can be shown to re-render exactly one Source.
 *
 * Nothing is fetched, nothing is generated by a provider, and no absolute host
 * path is written into the Project. Build with the separate command:
 *   viscraft build <project-directory>
 */
import { basename, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { makeSignalAsset } from '../lib/audio-fixture.mjs';
import {
  GLASS_PRODUCT_DIR,
  GLASS_PRODUCT_MODULE,
  GLASS_PRODUCT_RIGHTS,
  declareGlassDependencies,
} from '../../../../skills/viscraft/assets/studies/code-visuals/glass-product/three-files.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
const SCENE_HTML = 'glass-study-scene.html';
const SCENE_MJS = 'glass-study.mjs';
const MODULE_MJS = GLASS_PRODUCT_MODULE;
const MODULE_HTML = 'glass-product-scene.html';
const SCENE_RIGHTS = {
  origin:
    'original: the glass-study example scene, authored for Viscraft; it drives the MIT glass-product author module without modifying it',
  license: 'MIT',
  redistributable: true,
};

function slugToId(name) {
  const cleaned = String(name).toLowerCase().replace(/[^a-z0-9_-]+/g, '-').replace(/^-+|-+$/g, '') || 'study';
  return ('glass-study-' + (/^[a-z0-9]/.test(cleaned) ? cleaned : 'p-' + cleaned)).slice(0, 96);
}

export default async function ({ root, options, runtime }) {
  const { width = 640, height = 360, frames = 24, three } = options ?? {};
  for (const [name, value] of Object.entries({ width, height, frames })) {
    if (!Number.isInteger(value) || value <= 0) throw new Error(`"${name}" must be a positive integer`);
  }
  if (width % 2 !== 0 || height % 2 !== 0) throw new Error('"width" and "height" must be even');

  const fps = 24;
  const sampleRate = 48000;
  const channels = 2;
  const studySeconds = frames / fps;

  // ---- the reference module + pinned Three closure -------------------------
  // `options.three` is an explicit donor directory for the pinned closure; both
  // paths are verified against the study's declaration before anything is
  // written. There is no fallback to a Skill-neighbour install or a download.
  const threeDirectory = typeof three === 'string' && three.length > 0 ? three : undefined;
  const dependencies = await declareGlassDependencies({ runtime, root, threeDirectory });
  const threeFiles = dependencies.files.filter((file) => file.path.startsWith('vendor/'));

  // ---- two shots of the SAME re-authored product -----------------------------
  // The product variant (geometry + material) is shared; the shots differ in which
  // module beat they stage and how they light it. `study.duration` is this
  // Source's own length, the same convention the reusable module uses.
  const PRODUCT = {
    product: 'AURELIS',
    duration: studySeconds,
    accentA: '#ffb25e',
    accentB: '#ff5f8f',
    caseRx: 30,
    caseRz: 35,
    caseHl: 11,
  };
  const specs = [
    {
      id: 'study_detail',
      seed: 73141,
      study: { ...PRODUCT, shot: 'detail', exposureFrom: 0.92, exposureTo: 1.18, bloom: 0.34, pulse: 1.25 },
      intent: 'An intact single-bud detail shot on the module’s tight exploded-beat camera, its guide igniting as the exposure lifts.',
    },
    {
      id: 'study_hero',
      seed: 73142,
      study: { ...PRODUCT, shot: 'hero', exposureFrom: 1.08, exposureTo: 1.2, bloom: 0.3, pulse: 1 },
      intent: 'The same re-proportioned case and amber guide read as a whole product in the module’s hero beat.',
    },
  ];

  const resources = [SCENE_MJS, MODULE_MJS, ...threeFiles.map((file) => file.path)];
  const sources = specs.map((spec) => ({
    id: spec.id,
    kind: 'browser',
    output: 'picture',
    entry: SCENE_HTML,
    resources,
    bindings: [],
    params: { study: spec.study },
    seed: spec.seed,
    frames,
  }));

  const look = {
    id: 'glass_study',
    description:
      'An author-modified dark-studio glass product study: a narrower/deeper case, an amber light-guide material, and a held single-bud detail beat that ends on the guide’s ignition.',
  };
  const sceneId = 'scene_study';
  let cursor = 0;
  const shots = [];
  const placements = [];
  for (const spec of specs) {
    shots.push({ id: `shot_${spec.id}`, scene: sceneId, look: look.id, intent: spec.intent, targetFrames: frames });
    placements.push({
      id: `pl_${spec.id}`,
      shot: `shot_${spec.id}`,
      source: spec.id,
      inFrame: 0,
      outFrame: frames,
      startFrame: cursor,
      audio: 'mute',
    });
    cursor += frames;
  }
  const totalFrames = cursor;
  const totalSamples = Math.ceil((totalFrames / fps) * sampleRate);
  // Two real PCM beds; the authored clip timing and gain are unchanged.
  const bedSub = makeSignalAsset({
    id: 'bed_sub',
    path: 'bed-sub.wav',
    sampleRate,
    channels,
    samples: totalSamples,
    frequency: 58,
    waveform: 'sine',
  });
  const bedGlass = makeSignalAsset({
    id: 'bed_glass',
    path: 'bed-glass.wav',
    sampleRate,
    channels,
    samples: totalSamples,
    frequency: 740,
    waveform: 'triangle',
  });
  const audio = [
    { id: 'bed_sub', kind: 'asset', asset: 'bed_sub', inSample: 0, startSample: 0, durationSamples: totalSamples, gain: 0.05, fadeInSamples: Math.min(9600, Math.floor(totalSamples / 4)), fadeOutSamples: Math.min(14400, Math.floor(totalSamples / 2)) },
    { id: 'bed_glass', kind: 'asset', asset: 'bed_glass', inSample: 0, startSample: 0, durationSamples: totalSamples, gain: 0.015, fadeInSamples: Math.min(9600, Math.floor(totalSamples / 4)), fadeOutSamples: Math.min(14400, Math.floor(totalSamples / 2)) },
  ];

  const files = [
    { path: SCENE_HTML, sourcePath: join(HERE, SCENE_HTML) },
    { path: SCENE_MJS, sourcePath: join(HERE, SCENE_MJS) },
    { path: MODULE_MJS, sourcePath: join(GLASS_PRODUCT_DIR, MODULE_MJS) },
    { path: MODULE_HTML, sourcePath: join(GLASS_PRODUCT_DIR, MODULE_HTML) },
    ...dependencies.files,
    { path: bedSub.asset.path, bytes: bedSub.bytes },
    { path: bedGlass.asset.path, bytes: bedGlass.bytes },
  ];
  const assets = [
    { id: 'study_scene', path: SCENE_HTML, type: 'code', simulated: false, rights: SCENE_RIGHTS },
    { id: 'study_module', path: SCENE_MJS, type: 'code', simulated: false, rights: SCENE_RIGHTS },
    { id: 'glass_scene', path: MODULE_HTML, type: 'code', simulated: false, rights: GLASS_PRODUCT_RIGHTS },
    { id: 'glass_module', path: MODULE_MJS, type: 'code', simulated: false, rights: GLASS_PRODUCT_RIGHTS },
    ...dependencies.assets,
    bedSub.asset,
    bedGlass.asset,
  ];

  const project = {
    schemaVersion: 1,
    id: slugToId(basename(root)),
    revision: 1,
    title: 'GLASS STUDY — a different product out of the reusable glass Look',
    direction: {
      intent:
        'A technical authoring study, not a finished film: it takes the byte-identical glass-product Look and authors a different fictional product out of it — a narrower/deeper case with a lower lid, an amber light-guide palette, and one camera/lighting beat re-used from the module (its tight single-bud exploded-beat camera, held with the product whole and lit by an exposure ramp). Two picture Sources (close detail, hero) let a one-parameter edit prove per-Source reuse. Stylized product photography; not a real product, brand or photoreal claim.',
      looks: [look],
      transitions: [],
    },
    assets,
    bindings: {},
    handoff: dependencies.handoff,
    sources,
    composition: {
      output: { width, height, fps: { numerator: fps, denominator: 1 }, sampleRate, channels },
      scenes: [{ id: sceneId, description: 'One re-authored glass product, staged as a close detail and a hero.' }],
      shots,
      placements,
      transitions: [],
      audio,
    },
  };

  return { project, files };
}
